#!/usr/bin/env bash
# Round 391 PERF-13b-ii claims (L29 + L56). Run from the loop root. CLAIMS_STORE overrides the store path.
L=$(pwd); S=${CLAIMS_STORE:-/home/runner/czaba-project/store}; C=$S/app/contexts/ArrangementContext.tsx; ST=$S/app/lib/arrangement/strings.ts; EV=$S/app/lib/arrangement/__tests__/decoded-buffer-eviction-ui.test.tsx
echo "K1 $(python3 -I -c "import json;a=json.load(open('gates/gate-round-388.json'));b=json.load(open('gates/gate-round-389.json'));c=json.load(open('gates/gate-round-390.json'));print(a['status'],a['commit'][:7],b['status'],c['status'])")"
echo "K2 $(git -C $S rev-parse --short HEAD) $(git -C $S status --short --untracked-files=all | wc -l)"
echo "K3 $(cd $S && sha256sum -c $L/b-round-318/protected-sha256.txt 2>/dev/null | grep -c ': OK$')"
echo "K4 $(cd $S && sha256sum -c $L/b-round-390/r391-frozen-sha256.txt 2>/dev/null | grep -vc ': OK$') $(wc -l < b-round-390/r391-frozen-sha256.txt)"
echo "K5 $(python3 -I -c "import json;d=json.load(open('regression-last.json'));print(d['date'],d['round'])")"
echo "K6 $(curl -s -o /dev/null -w '%{http_code}' --max-time 30 http://127.0.0.1:5173/studio-lab)"
echo "K7 $(python3 -I -c "import json;c=json.load(open('c-round-390.json'));print(c['taskStatus'],len(c['failed']),len(c['bugs']),c['browserVerified'],c['realVerified'])")"
echo "K8 sourceNotLoaded-calls $(grep -c 'studioLibraryStrings.sourceNotLoaded(' $C)"
echo "K9 play-refusal $(grep -c 'setStatus(studioLibraryStrings.sourceNotLoaded(source?.title ?? awaiting\[0\]));' $C)"
echo "K10 awaiting-filter $(grep -c "latestRef.current.sourceStates\[id\]?.status === 'ready' && !decodedBuffers.has(id)," $C)"
echo "K11 prepareExportSources-calls $(grep -c 'await prepareExportSources(arrangement, controller);' $C) exportFailed-uses $(grep -c 'studioExportStrings.exportFailed(failedSource)' $C)"
echo "K12 preview-then $(grep -c 'void ensureDecoded(\[sourceId\]).then(() => {' $C) superseded-return $(grep -c 'if (previewRequestRef.current !== sourceId) {' $C)"
echo "K13 owner-check $(grep -c 'const controller = owner?.collection === collection ? owner.controller : null;' $C) aborted-check-in-then $(grep -c 'if (signal.aborted) {' $C)"
echo "K14 playingFrom-write $(grep -c "insertMarkerStatusKind(text) === 'stopped' || text === studioPlaybackStrings.scheduleFailed" $C) beginPointerGesture $(grep -c 'const beginPointerGesture = useCallback' $C)"
echo "K15 strings sourceNotLoaded $(grep -c 'sourceNotLoaded: (title: string): string => `“${title}” has not loaded yet.`,' $ST) sourceFailed $(grep -c '`“${title}” failed to load — details are in the library.`,' $ST) exportFailed $(grep -c 'exportFailed: (reason: string): string => `Export failed — no file was created. ${reason}`,' $ST) new-keys $(grep -c 'sourceDecoding\|sourceReady' $ST)"
echo "K16 EV-pins EV3-337 $(sed -n 337p $EV | grep -c 'sourceNotLoaded(BIG_TITLE)') EV9-508 $(sed -n 508p $EV | grep -c 'sourceNotLoaded(BIG_TITLE)') EV9-506-statusBefore $(sed -n 507p $EV | grep -c 'toBe(statusBefore)') tests $(grep -c "^  it('EV" $EV)"
echo "K17 strings.test formatter-table sourceNotLoaded $(grep -c "sourceNotLoaded: \[lib.sourceNotLoaded('Hit')\]," $S/app/lib/arrangement/__tests__/strings.test.ts)"
echo "K18 budgets $(python3 -I -c "import json;d={r['id']:r for r in json.load(open('$S/perf/budgets.resources.json'))};print(*[d[k]['mode'] for k in ('res.mem.pcm-live-mib-ready','res.mem.pcm-live-decode-mib-ready','res.mem.pcm-live-count-ready','res.mem.pcm-live-mib-after-add')])") budget-consumers $(grep -rl 'budgets.resources' $S/perf $S/app $S/scripts 2>/dev/null | wc -l)"
echo "K19 demo canReloadSource $(grep -c 'canReloadSource: (source) => Object.hasOwn(demoUrls, source.id),' $S/app/data/studio-lab-demo.ts) middle-east-title $(grep -c "title: 'Middle East — public preview'," $S/app/data/studio-lab-demo.ts)"
echo "K20 sketch $(grep -cE 'res.mem.pcm-live-mib-ready +assert median +31.9 .*PASS' b-round-390/perf-sketch-391.log) $(grep -cE 'res.mem.pcm-live-decode-mib-ready +assert median +0 .*PASS' b-round-390/perf-sketch-391.log) $(grep -c '1 passed' b-round-390/perf-sketch-391.log) patch-sha $(sha256sum b-round-390/sketch-391.patch.txt | cut -c1-8)"
echo "K21 mutant $(grep -cE 'pcm-live-mib-ready +assert median +124 .*FAIL' b-round-390/mutants/mutant-MU-391-NOTHING-EVICTABLE.log) $(grep -cE 'pcm-live-decode-mib-ready +assert median +92.2 .*FAIL' b-round-390/mutants/mutant-MU-391-NOTHING-EVICTABLE.log)"
echo "K22 l23-preapply $(sed 's/\x1b\[[0-9;]*m//g' b-round-390/l23-preapply-391.log | grep -c '× ST12') $(sed 's/\x1b\[[0-9;]*m//g' b-round-390/l23-preapply-391.log | grep -c '× EV3: Play is refused') $(sed 's/\x1b\[[0-9;]*m//g' b-round-390/l23-preapply-391.log | grep -oE 'Tests +[0-9]+ failed \| [0-9]+ passed' | head -1)"
echo "K23 doc-next-free $(ls $S/docs/implementation/2026/quarter-IV/ | grep -c '^251-') last $(ls $S/docs/implementation/2026/quarter-IV/ | sort | tail -1 | cut -c1-3)"
echo "K24 gate388 durations $(grep -E 'decoded-buffer-eviction-ui|failed-source-refusal|strings.test.ts|name-bar-hint-ui' gates/round-388/verify.log | sed 's/\x1b\[[0-9;]*m//g' | grep -oE '[a-z-]+\.test\.tsx? \([0-9]+ tests\) [0-9]+ms' | tr '\n' ';')"
echo "K26 status-testid $(grep -c 'data-testid="arrangement-status"' $S/app/components/arrangement/StudioWorkspace.tsx) aria-live $(sed -n 3654p $S/app/components/arrangement/StudioWorkspace.tsx | grep -c 'aria-live="polite"') ready-text $(grep -c "'Demo collection ready. Drag a sound onto a track, or press Enter to add it. Press ? for shortcuts.'," $S/app/lib/arrangement/collection.ts)"
echo "K25 $(for f in tasks/round-390.md tasks/round-382.md tasks/round-386.md c-round-390.json c-round-390.md c-round-389/perf-results/latest-resources.json b-round-390/grants-391.txt b-round-390/r391-frozen-sha256.txt b-round-390/sketch-391.patch.txt b-round-390/sketch-391-budgets.resources.json b-round-390/perf-sketch-391.log b-round-390/perf-sketch-391-latest-resources.json b-round-390/mutants/mutant-MU-391-NOTHING-EVICTABLE.log b-round-390/l23-preapply-391.log b-round-385/probe/preview-while-playing.mjs c-round-382/lib.mjs b-round-318/protected-sha256.txt b-round-390/claims-391.sh; do test -e $f || echo MISSING:$f; done; echo checked)"
